import React, { useState, useEffect } from 'react';
import { useStore } from '../../store/useStore';

export default function StudentProfile() {
  var store = useStore();
  var [name, setName] = useState('');
  var [bio, setBio] = useState('');
  var [avatarUrl, setAvatarUrl] = useState('');
  var [department, setDepartment] = useState('');
  var [year, setYear] = useState('1st Year');
  var [loading, setLoading] = useState(false);
  var [success, setSuccess] = useState('');
  var [subs, setSubs] = useState([]);

  useEffect(function() {
    store.loadProfile().then(function(p) {
      if (p) {
        setName(p.name || '');
        setBio(p.bio || '');
        setAvatarUrl(p.avatar_url || '');
        setDepartment(p.department || '');
        setYear(p.year || '1st Year');
      }
    });
    store.loadSubmissions(store.currentUser.user_id).then(function(d) { setSubs(d); });
  }, []); // eslint-disable-line

  async function handleSave(e) {
    e.preventDefault();
    setLoading(true); setSuccess('');
    try {
      await store.updateProfile({ name: name, bio: bio, avatar_url: avatarUrl, department: department, year: year });
      setSuccess('Profile updated!');
      store.loadProfile();
    } catch (e) { alert(e.message); }
    setLoading(false);
  }

  var avgScore = subs.length > 0 ? Math.round(subs.reduce(function(a, s) { return a + (s.total_score || 0); }, 0) / subs.length) : 0;

  return (
    <div className="fade-up">
      <div className="page-title" style={{ marginBottom: 24 }}>👤 My Profile</div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24 }}>
        <div className="card">
          <div style={{ textAlign: 'center', marginBottom: 24 }}>
            <div style={{ width: 80, height: 80, borderRadius: '50%', background: 'linear-gradient(135deg, var(--accent), var(--accent2))', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto', fontSize: '2rem', color: '#fff', fontWeight: 700 }}>
              {avatarUrl ? <img src={avatarUrl} alt="" style={{ width: 80, height: 80, borderRadius: '50%', objectFit: 'cover' }} /> : (name || 'S').charAt(0).toUpperCase()}
            </div>
            <div style={{ fontWeight: 700, fontSize: '1.2rem', marginTop: 12 }}>{name}</div>
            <div style={{ color: 'var(--text3)', fontSize: '0.85rem' }}>{store.currentUser.email}</div>
          </div>
          <form onSubmit={handleSave}>
            <div className="form-group"><label className="form-label">Full Name</label><input className="form-input" value={name} onChange={function(e) { setName(e.target.value); }} maxLength={100} /></div>
            <div className="form-group"><label className="form-label">Bio</label><textarea className="form-textarea" value={bio} onChange={function(e) { setBio(e.target.value); }} rows={2} /></div>
            <div className="form-group"><label className="form-label">Avatar URL</label><input className="form-input" value={avatarUrl} onChange={function(e) { setAvatarUrl(e.target.value); }} placeholder="https://..." /></div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
              <div className="form-group"><label className="form-label">Department</label><input className="form-input" value={department} onChange={function(e) { setDepartment(e.target.value); }} /></div>
              <div className="form-group"><label className="form-label">Year</label><select className="form-select" value={year} onChange={function(e) { setYear(e.target.value); }}><option>1st Year</option><option>2nd Year</option><option>3rd Year</option><option>4th Year</option></select></div>
            </div>
            {success && <div style={{ padding: 10, background: 'rgba(22,163,74,0.08)', borderRadius: 8, color: 'var(--success)', fontSize: '0.85rem', marginBottom: 12 }}>✅ {success}</div>}
            <button className="btn btn-primary" disabled={loading}>{loading ? 'Saving...' : '💾 Save Profile'}</button>
          </form>
        </div>
        <div>
          <div className="card" style={{ marginBottom: 16 }}>
            <div className="card-title">📊 Performance Overview</div>
            <div className="stats-grid" style={{ marginTop: 16, marginBottom: 0 }}>
              <div className="stat-card"><div className="stat-value">{subs.length}</div><div className="stat-label">Exams Taken</div></div>
              <div className="stat-card"><div className="stat-value" style={{ color: 'var(--success)' }}>{avgScore}%</div><div className="stat-label">Avg Score</div></div>
            </div>
          </div>
          <div className="card">
            <div className="card-title">📈 Score History</div>
            <div style={{ marginTop: 16 }}>
              {subs.length === 0 ? <div style={{ color: 'var(--text3)', fontSize: '0.85rem' }}>No exams taken yet</div> : (
                <div style={{ display: 'flex', alignItems: 'flex-end', gap: 4, height: 120 }}>
                  {subs.slice(-10).map(function(s, i) {
                    var pct = s.total_marks > 0 ? (s.total_score / s.total_marks) * 100 : 0;
                    return <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 }}>
                      <div style={{ fontSize: '0.65rem', color: 'var(--text3)' }}>{Math.round(pct)}%</div>
                      <div style={{ width: '100%', height: pct + '%', minHeight: 4, background: 'linear-gradient(to top, var(--accent), var(--accent-light))', borderRadius: 4 }}></div>
                    </div>;
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
